def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(v in (2, 8) for v in row))
    src = grid[r]
    for c, color in enumerate(src):
        if color not in (2, 8):
            continue
        n = 0
        j = c + 1
        while j < len(src) and src[j] == 1:
            n += 1
            j += 1
        for k in range(1, min(n, r) + 1):
            out[r-k][c] = 1
        if n + 1 <= r:
            out[r-n-1][c] = color
    return out
